using System.Text.Json;
using System.Text.Json.Serialization;
using System.Text.Json.Serialization.Metadata;

// --- 1. GetTypeInfo<T>(): strongly-typed metadata retrieval ---

var options = new JsonSerializerOptions(JsonSerializerDefaults.Web);

JsonTypeInfo<Person> personInfo = options.GetTypeInfo<Person>();
Console.WriteLine($"GetTypeInfo<Person> returned type: {personInfo.Type.Name}");

string json = JsonSerializer.Serialize(new Person("Ada", 38), personInfo);
Console.WriteLine($"Serialized: {json}");

// --- 2. TryGetTypeInfo<T>(): check-without-throwing ---

// The default resolver knows about Person (it uses reflection),
// so this will succeed:
if (options.TryGetTypeInfo<Person>(out JsonTypeInfo<Person>? resolvedInfo))
{
    Console.WriteLine($"TryGet succeeded for Person – Type: {resolvedInfo!.Type.Name}");
}
else
{
    Console.WriteLine("TryGet failed for Person");
}

// Build options with a source-gen context that only knows about Person.
// Asking for int[] will fail gracefully — no exception.
var limited = new JsonSerializerOptions { TypeInfoResolver = PersonOnlyContext.Default };

if (limited.TryGetTypeInfo<int[]>(out JsonTypeInfo<int[]>? arrayInfo))
{
    Console.WriteLine($"TryGet succeeded for int[] – Type: {arrayInfo!.Type.Name}");
}
else
{
    Console.WriteLine("TryGet for int[] returned false (type not in resolver) — no exception thrown");
}

// ---

public record Person(string Name, int Age);

[JsonSerializable(typeof(Person))]
public partial class PersonOnlyContext : JsonSerializerContext;

